/** Static bundler for this project's acyclic named-import ESM modules.
 * It generates ordinary JavaScript; no eval, Function, runtime loader or third-party dependency.
 * This intentionally rejects unsupported import/export forms rather than being a general JS bundler.
 */
import { readFile } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
export async function bundleWorker(entry) {
  const modules = [], ids = new Map(), visiting = new Set();
  async function visit(path) {
    path = resolve(path);
    if (visiting.has(path)) throw new Error(`Worker module cycle: ${path}`);
    if (ids.has(path)) return ids.get(path);
    visiting.add(path);
    let source = await readFile(path, 'utf8');
    const statements = [...source.matchAll(/^(?:import\s+\{([^}]+)\}\s+from\s+(['"])([^'"]+)\2\s*;|export\s+\*\s+from\s+(['"])([^'"]+)\4\s*;|export\s+\{([^}]+)\}\s+from\s+(['"])([^'"]+)\7\s*;)/gm)];
    const spreads = [];
    for (const match of statements) {
      const dependency = match[3] ?? match[5] ?? match[8];
      if (!dependency.startsWith('.')) throw new Error(`Unresolved worker dependency ${dependency}`);
      const id = await visit(resolve(dirname(path), dependency));
      if (match[1]) source = source.replace(match[0], `const {${match[1].replace(/\s+as\s+/g, ':')}} = __module${id};`);
      else { source = source.replace(match[0], '');if(match[6]){for(const item of match[6].split(',').map(s=>s.trim()).filter(Boolean)){const [name,alias]=item.split(/\s+as\s+/);if(!/^[\w$]+$/.test(name)||alias&&!/^[\w$]+$/.test(alias))throw new Error('Unsupported named re-export');spreads.push(`${alias??name}:__module${id}.${name}`);}}else spreads.push(`...__module${id}`); }
    }
    const exports = [];
    source = source.replace(/^export\s+(class|(?:async\s+)?function\*?|const|let)\s+([\w$]+)/gm, (_, kind, name) => { exports.push(name); return `${kind} ${name}`; });
    source=source.replace(/^export\s+\{([^}]+)\}\s*;/gm,(_,list)=>{for(const item of list.split(',').map(s=>s.trim()).filter(Boolean)){const [name,alias]=item.split(/\s+as\s+/);if(!/^[\w$]+$/.test(name)||alias&&!/^[\w$]+$/.test(alias))throw new Error('Unsupported named export');exports.push(alias?`${alias}:${name}`:name);}return '';});
    if (/^(?:import|export)\s/m.test(source)) throw new Error(`Unsupported module syntax in ${path}`);
    const id = modules.length;
    modules.push(`const __module${id} = (() => {\n${source}\nreturn {${[...spreads,...exports].join(',')}};\n})();`);
    ids.set(path, id); visiting.delete(path); return id;
  }
  await visit(entry);
  return `/* SharpForge static worker bundle. Generated by scripts/bundle-worker.js. */\n'use strict';\n(() => {\n${modules.join('\n')}\n})();\n`;
}
